def delta_hat():
    # states: 0=start, 1, 2, d=dead
    state = 0
    for sym in '1101':
        if state == 0:
            state = 1 if sym == '1' else None
        elif state == 1:
            state = 2 if sym == '1' else None
        elif state == 2:
            state = 2 if sym == '0' else None
        else:
            state = None
        if state is None:
            break
    # accept if state == 2
    print(1 if state == 2 else 0)

