#include <stdio.h>
int main(){
    char *w = "1101";
    int state = 0; // q0
    for(int i=0; w[i]!='\0'; ++i){
        char c = w[i];
        if(state==0){ state = (c=='1')?1:-1; }
        else if(state==1){ state = (c=='1')?2:-1; }
        else if(state==2){ state = (c=='0')?2:-1; }
        else { state = -1; }
        if(state==-1) break;
    }
    printf("%d\n", (state==2)?1:0);
    return 0;
}
